{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name IN ('SELECT Trip','SELECT ts.trip','TripRepository.findAll') GROUP BY 1,2",
          "claim": "travel-service 'SELECT Trip' DB spans hang about 30s with errors, while the real 'SELECT ts.trip' client calls take about 1ms."
        },
        {
          "kind": "log",
          "sql": "SELECT level, left(CAST(message AS VARCHAR),160) msg, count(*) n FROM abnormal_logs WHERE service_name='ts-travel-service' AND level IN ('ERROR','WARN') GROUP BY 1,2 ORDER BY n DESC",
          "claim": "travel-service logs HikariPool 'Connection is not available, request timed out after 30000ms' and JDBC 'Communications link failure' errors."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, count(*) n, round(avg(try_cast(value AS DOUBLE)),2) avgv, round(max(try_cast(value AS DOUBLE)),2) maxv FROM abnormal_metrics_sum WHERE service_name='ts-travel-service' AND metric IN ('db.client.connections.pending_requests','db.client.connections.max','db.client.connections.timeouts') GROUP BY 1",
          "claim": "travel-service DB connection pool (max 10) shows pending requests up to 4 and connection timeouts during the incident."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "route-plan-service calls to travel-service take about 30s and 5 of 6 fail, passing the DB timeout upward."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "travel-plan-service calls to route-plan-service take about 30s and 5 of 6 fail."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY 1,2",
          "claim": "ui-dashboard calls to travel-plan-service take about 30s and 5 of 5 fail, reaching the user-facing tier."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) child_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "ui-dashboard calls to travel-service take about 30s and 16 of 18 fail, a direct user-facing impact.",
        }
      ]
    }
  ]
}
